    {
      "card_ids": ["C07"],
      "claim": "A structurally related small molecule containing a fluorophenyl, nitrile, and amide (NA-014 analog) achieved a brain-to-plasma ratio of 1.32 in mice, indicating meaningful brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A lipophilic basic molecule with fluorophenyl and trifluoromethyl motifs crossed the BBB in vivo in mice, demonstrating that these structural features are compatible with CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A fluorophenyl-containing basic molecule showed rapid and substantial brain accumulation in a monkey PET study, supporting CNS penetration for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A fluorobenzamide piperazine analog penetrated the BBB and distributed throughout the brain in a rhesus monkey PET study, providing direct evidence that similar amide/fluorophenyl scaffolds achieve CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Bicalutamide, a neutral sulfonyl-containing analog with fluorophenyl/CF3/nitrile motifs, showed poor BBB penetration, but its relevance is limited by major physicochemical differences (sulfonyl, hydroxyl, lack of basic amine) from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the query is a small, lipophilic, basic amide with fluorophenyl/CF3/nitrile motifs; multiple structurally related analogs demonstrate meaningful brain penetration in vivo, while negative records involve dissimilar chemotypes (acids, sulfones, peptides, metal complexes).",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement exists for the query molecule itself.",
    "Potential P-glycoprotein efflux liability of the secondary amine was not directly assessed.",
    "Unbound brain concentrations and target engagement were not measured in the supporting records.",
    "Some supporting records rely on single time-point or total radioactivity measurements rather than steady-state partitioning."
  ],
